            continue

        # The title ends at the first "]", which must be followed at once by "(".
        close = line.find("]", 3)
        if close == -1 or line[close + 1:close + 2] != "(":
            continue

        # The url ends at the first ")" after the "(".
        paren = line.find(")", close + 2)
        if paren == -1:
