Here's a solution that assumes a table with a column named `Scope` whose value is `in` or `out`. The column name and value are parameters, so you can change them if your table differs.

```python
"""Parse a Markdown scope table and list the rows marked "in"."""

import re

_SEPARATOR_CELL = re.compile(r"^:?-{3,}:?$")


def _split_row(line: str) -> list[str]:
    """Split one Markdown table line into stripped cells.

    Handles optional leading/trailing pipes and escaped pipes (\\|).
    """
    line = line.strip()
    if line.startswith("|"):
        line = line[1:]
    if line.endswith("|") and not line.endswith("\\|"):
        line = line[:-1]
    cells = re.split(r"(?<!\\)\|", line)
    return [cell.strip().replace("\\|", "|") for cell in cells]


def _is_separator(line: str) -> bool:
    cells = _split_row(line)
    return bool(cells) and all(_SEPARATOR_CELL.match(c) for c in cells)


def parse_first_table(markdown: str) -> tuple[list[str], list[list[str]]]:
    """Return (headers, rows) for the first Markdown table in the text."""
    lines = markdown.splitlines()
    for i in range(len(lines) - 1):
        if "|" in lines[i] and _is_separator(lines[i + 1]):
            headers = _split_row(lines[i])
            rows = []
            for line in lines[i + 2:]:
                if not line.strip() or "|" not in line:
                    break  # table ends at a blank or non-table line
                cells = _split_row(line)
                cells += [""] * (len(headers) - len(cells))  # pad short rows
                rows.append(cells[:len(headers)])
            return headers, rows
    raise ValueError("No Markdown table found")


def list_in_rows(markdown: str, column: str = "Scope", value: str = "in") -> list[dict[str, str]]:
    """Return every row whose `column` equals `value` (case-insensitive).

    Each row is returned as a dict mapping header names to cell values.
    """
    headers, rows = parse_first_table(markdown)

    lookup = {h.lower(): h for h in headers}
    if column.lower() not in lookup:
        raise KeyError(f"Column {column!r} not found in headers {headers}")
    key = lookup[column.lower()]
    index = headers.index(key)

    return [
        dict(zip(headers, row))
        for row in rows
        if row[index].lower() == value.lower()
    ]


# ---------------------------------------------------------------------------
# Tests (run with: pytest test_scope_table.py)
# ---------------------------------------------------------------------------

SAMPLE = """\
# Project scope

| Item            | Scope | Notes                 |
|-----------------|-------|-----------------------|
| Login page      | in    | Required for launch   |
| Admin dashboard | out   | Phase 2               |
| Password reset  | IN    | Case-insensitive test |
| Dark mode       | out   |                       |

Some trailing prose.
"""


def test_lists_only_in_rows():
    rows = list_in_rows(SAMPLE)
    assert [r["Item"] for r in rows] == ["Login page", "Password reset"]


def test_rows_are_dicts_with_all_headers():
    rows = list_in_rows(SAMPLE)
    assert rows[0] == {
        "Item": "Login page",
        "Scope": "in",
        "Notes": "Required for launch",
    }


def test_value_match_is_case_insensitive():
    rows = list_in_rows(SAMPLE)
    assert any(r["Scope"] == "IN" for r in rows)


def test_no_in_rows_returns_empty_list():
    md = "| Item | Scope |\n|---|---|\n| A | out |\n"
    assert list_in_rows(md) == []


def test_table_without_leading_or_trailing_pipes():
    md = "Item | Scope\n--- | ---\nA | in\nB | out\n"
    assert list_in_rows(md) == [{"Item": "A", "Scope": "in"}]


def test_escaped_pipe_in_cell():
    md = "| Item | Scope |\n|---|---|\n| a \\| b | in |\n"
    assert list_in_rows(md) == [{"Item": "a | b", "Scope": "in"}]


def test_alignment_colons_in_separator():
    md = "| Item | Scope |\n|:---|:---:|\n| A | in |\n"
    assert list_in_rows(md) == [{"Item": "A", "Scope": "in"}]


