    assert list_in_rows(md) == [{"Item": "A", "Scope": "in", "Notes": ""}]


def test_table_ends_at_blank_line():
    md = "| Item | Scope |\n|---|---|\n| A | in |\n\n| B | in |\n"
    assert list_in_rows(md) == [{"Item": "A", "Scope": "in"}]


def test_custom_column_and_value():
