            continue
        if in_fence:
            continue
        match = _LINK_RE.fullmatch(line.rstrip())
        if match is None:
            continue
        title, url, desc = match.group(1), match.group(2), match.group(3)
        result.append((title, url, (desc or "").strip()))
    return result


